foreach($completeness_dictionary as $lang=>$items){ if(isset($ui_dictionary[$lang])) $ui_dictionary[$lang]=array_merge($ui_dictionary[$lang],$items); else $ui_dictionary[$lang]=$items; }


function translate_rendered_output($html) {
    global $current_language, $ui_dictionary;
    if ($current_language === 'en' || empty($html) || empty($ui_dictionary[$current_language])) return $html;
    $map = $ui_dictionary[$current_language];
    // Longest first prevents partial phrases from corrupting longer labels.
    uksort($map, function($a, $b) { return strlen($b) <=> strlen($a); });
    foreach ($map as $from => $to) {
        $html = str_replace($from, $to, $html);
    }
    return $html;
}

function language_selector_markup() {
    global $current_language;
    $path = strtok($_SERVER['REQUEST_URI'] ?? '/', '?');
    $query = $_GET;
    unset($query['lang']);
    $base = $path . (!empty($query) ? '?' . http_build_query($query) . '&' : '?');
    return '<div class="global-language-switcher" aria-label="Language selector">'
        . '<span aria-hidden="true">🌐</span>'
        . '<select onchange="window.location.href=this.value" aria-label="Language">'
        . '<option value="'.htmlspecialchars($base.'lang=en', ENT_QUOTES).'" '.($current_language==='en'?'selected':'').'>English</option>'
        . '<option value="'.htmlspecialchars($base.'lang=om', ENT_QUOTES).'" '.($current_language==='om'?'selected':'').'>Afaan Oromoo</option>'
        . '<option value="'.htmlspecialchars($base.'lang=am', ENT_QUOTES).'" '.($current_language==='am'?'selected':'').'>አማርኛ</option>'
        . '</select></div>';
}

function inject_global_language_selector($html) {
    global $conn;
    $brandCss = '';

    // Branding is injected on EVERY rendered page.  Some pages already have
    // their own language selector, so branding must not depend on whether the
    // selector exists.
    if (isset($conn) && $conn) {
        @mysqli_query($conn, "CREATE TABLE IF NOT EXISTS site_settings (
            setting_key VARCHAR(100) NOT NULL PRIMARY KEY,
            setting_value TEXT NULL,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

        $pc = '#003DA5';
        $sc = '#EAAA00';
        $gb = '#f5f7fa';
        $nb = $sc;
        $r = @mysqli_query($conn, "SELECT setting_key,setting_value FROM site_settings WHERE setting_key IN ('primary_color','secondary_color','global_background_color','navbar_color')");
        if ($r) {
            while ($x = mysqli_fetch_assoc($r)) {
                $v = $x['setting_value'] ?? '';
                if ($x['setting_key']==='primary_color' && preg_match('/^#[0-9A-Fa-f]{6}$/',$v)) $pc=$v;
                if ($x['setting_key']==='secondary_color' && preg_match('/^#[0-9A-Fa-f]{6}$/',$v)) $sc=$v;
                if ($x['setting_key']==='global_background_color' && preg_match('/^#[0-9A-Fa-f]{6}$/',$v)) $gb=$v;
                if ($x['setting_key']==='navbar_color' && preg_match('/^#[0-9A-Fa-f]{6}$/',$v)) $nb=$v;
            }
        }

        // Apply saved branding dynamically across the system. The admin
        // branding page writes these values to site_settings; every rendered
        // page receives the same CSS variables so changes are immediately
        // reflected after Save + refresh.
        $applyGlobal = true;
        $r2 = @mysqli_query($conn, "SELECT setting_key,setting_value FROM site_settings WHERE setting_key='apply_global_background' LIMIT 1");
        if ($r2 && ($x2 = mysqli_fetch_assoc($r2))) $applyGlobal = (($x2['setting_value'] ?? '1') === '1');

        $brandCss = '<style id="global-branding-style">'
            .':root{--brand-primary:'.htmlspecialchars($pc,ENT_QUOTES).';--brand-secondary:'.htmlspecialchars($sc,ENT_QUOTES).';--brand-navbar:'.htmlspecialchars($nb,ENT_QUOTES).';--brand-global-bg:'.htmlspecialchars($gb,ENT_QUOTES).'}'
            .'body{--brand-primary:'.htmlspecialchars($pc,ENT_QUOTES).';--brand-secondary:'.htmlspecialchars($sc,ENT_QUOTES).'}'
            // Primary brand color: headings, links, primary controls.
            .'h1,h2,h3,h4,h5,h6,.section-title,.card-title,.text-primary{color:var(--brand-primary)!important;}'
            .'.btn-primary,.homepage-action-btn{background-color:var(--brand-primary)!important;border-color:var(--brand-primary)!important;}'
            .'.btn-outline-primary{border-color:var(--brand-primary)!important;color:var(--brand-primary)!important;}'
            .'.btn-outline-primary:hover{background-color:var(--brand-primary)!important;color:#fff!important;}'
            // Secondary brand color: accents, warning/info controls and focus.
            .'.btn-warning,.btn-info{background-color:var(--brand-secondary)!important;border-color:var(--brand-secondary)!important;color:#fff!important;}'
            .'.form-control:focus,.form-select:focus{border-color:var(--brand-secondary)!important;box-shadow:0 0 0 .2rem color-mix(in srgb,var(--brand-secondary) 20%,transparent)!important;}'
            .'.card-header,.modal-header{background:linear-gradient(135deg,var(--brand-primary),var(--brand-secondary))!important;}'
            // Navbar/header keeps its own saved navbar color.
            .'.navbar-custom,.dashboard-top,.admin-sidebar{background:var(--brand-navbar)!important;}'
            // Public homepage has a few inline colors; these rules override them safely.
            .'.home-page > div:first-of-type{background-color:var(--brand-navbar)!important;}'
            .'.home-page .nav-button,.home-page .btn-warning{background-color:var(--brand-secondary)!important;border-color:var(--brand-secondary)!important;}'
            .'.home-page #footer{background-color:var(--brand-navbar)!important;}'
            .'.home-page .hero{background-color:var(--brand-primary)!important;}'
            .'.home-page .section-title{color:var(--brand-primary)!important;}'
            // The optional checkbox controls whether the selected global color
            // is propagated to page/section surfaces. Header/navbar is excluded.
            .($applyGlobal
                ? 'html,body,main,.page-bg,.page-background,.page-wrapper,.main-content,.content-wrapper,.dashboard-content,.admin-content,.receptionist-content,.teller-content,.customer-content{background-color:var(--brand-global-bg)!important;}'
                  .'.dynamic-brand-section,.home-page #services,.home-page #education,.home-page #working-hours,.home-page #about-us,.home-page #contact,.home-page #feedback{background-color:var(--brand-global-bg)!important;}'
                : 'html,body{background-color:var(--brand-global-bg)!important;}')
            // Header/navbar and footer intentionally remain on their original
            // static colors. The hero also keeps its original presentation.
            .'body.home-page .site-navbar-shell,.home-page .navbar-custom{background:#EAAA00!important;}'
            .'body.home-page footer{background:#003DA5!important;color:#fff!important;}'
            // Footer is static blue, so all footer text must stay high-contrast white.
            .'.home-page footer h1,.home-page footer h2,.home-page footer h3,.home-page footer h4,.home-page footer h5,.home-page footer h6{color:#fff!important;}'
            .'.home-page footer p,.home-page footer .text-center,.home-page footer .mb-0{color:#fff!important;}'
            .'.home-page footer a,.home-page footer a:visited{color:#fff!important;text-decoration:none;}'
            .'.home-page footer a:hover,.home-page footer a:focus{color:#ffd166!important;text-decoration:underline;}'
            .'.home-page footer hr{border-color:rgba(255,255,255,.65)!important;opacity:1;}'
            .'</style>';
    }

    $css = '<style id="global-language-style">.global-language-switcher{position:fixed;top:12px;right:16px;z-index:99999;display:flex;align-items:center;gap:6px;padding:6px 9px;border-radius:10px;background:rgba(255,255,255,.96);box-shadow:0 4px 18px rgba(0,0,0,.12);font:500 13px/1.2 Arial,sans-serif}.global-language-switcher select{border:1px solid #d5dbe3;border-radius:7px;padding:5px 25px 5px 8px;background:#fff;font:inherit;cursor:pointer}.global-language-switcher span{font-size:16px}@media(max-width:700px){.global-language-switcher{top:8px;right:8px}.global-language-switcher select{max-width:130px}}body{padding-top:0}</style>';

    $selector = '';
    if (stripos($html, 'global-language-switcher') === false && stripos($html, 'language-switcher') === false) {
        $selector = language_selector_markup();
    }

    if (stripos($html, '</head>') !== false) {
        $html = preg_replace('/<\/head>/i', $css . $brandCss . '</head>', $html, 1);
    } else {
        $html = $css . $brandCss . $html;
    }
    if ($selector !== '') {
        if (stripos($html, '<body') !== false) $html = preg_replace('/(<body[^>]*>)/i', '$1' . $selector, $html, 1);
        else $html = $selector . $html;
    }
    return $html;
}

if (!defined('LANGUAGE_OUTPUT_BUFFER_ACTIVE')) {
    define('LANGUAGE_OUTPUT_BUFFER_ACTIVE', true);
    ob_start(function($html) {
        $html = translate_rendered_output($html);
        return inject_global_language_selector($html);
    });
}
?>
